const f = $input.first().json;
const max = parseInt(f['Max Results'], 10) || 20;
return [{ json: {
  search: `${f['Business Type']} in ${f['City or Area']}`,
  apifyInput: {
    searchStringsArray: [f['Business Type']],
    locationQuery: f['City or Area'],
    countryCode: String(f['Country Code'] || 'us').toLowerCase().trim(),
    maxCrawledPlacesPerSearch: max,
    language: 'en',
    skipClosedPlaces: true,
    maxReviews: 0,
    maxImages: 0,
    maxQuestions: 0
  }
}}];

// Clean Apify output + remove duplicates (same place OR same website = same business)
const search = $('Build Apify Input').first().json.search;
const seen = new Set();
const out = [];
// n8n Code sandbox has no URL() class -> plain string/regex helpers
const cleanUrl = (u) => {
  const [base, rest] = String(u || '').split('?');
  if (rest === undefined) return base;
  const kept = rest.split('#')[0].split('&').filter(p => p && !/^(utm_|gclid|fbclid|sc_cid|_vsrefdom|y_source|msclkid)/i.test(p));
  return base + (kept.length ? '?' + kept.join('&') : '');
};
const hostOf = (u) => { const m = String(u || '').match(/^https?:\/\/([^\/?#:]+)/i); return m ? m[1].toLowerCase().replace(/^www\./, '') : ''; };
for (const it of $input.all()) {
  const p = it.json;
  if (!p || !p.placeId || seen.has(p.placeId) || p.permanentlyClosed) continue;
  seen.add(p.placeId);
  const site = cleanUrl(String(p.website || '').trim());
  const isSocial = /(instagram\.com|facebook\.com|fb\.com|linktr\.ee|wa\.me|tiktok\.com|m\.me)/i.test(site);
  const digits = String(p.phoneUnformatted || p.phone || '').replace(/\D/g, '');
  out.push({ json: {
    place_id: p.placeId,
    business_name: p.title || '',
    category: p.categoryName || '',
    address: p.address || '',
    city: p.city || '',
    phone: p.phone || p.phoneUnformatted || '',
    website: isSocial ? '' : site,
    social_url: isSocial ? site : '',
    wa_number: digits.length >= 10 ? digits : '',
    unclaimed_profile: p.claimThisBusiness === true,
    rating: p.totalScore || 0,
    reviews_count: p.reviewsCount || 0,
    maps_url: p.url || '',
    has_website: !!site && !isSocial,
    search,
    scraped_at: new Date().toISOString()
  }});
}
// Same website listed twice (e.g. practice + doctor profile) -> keep the listing with more reviews
const byDomain = new Map();
for (const o of out) {
  const dom = hostOf(o.json.website);
  const key = dom || o.json.place_id;
  const prev = byDomain.get(key);
  if (!prev || (o.json.reviews_count || 0) > (prev.json.reviews_count || 0)) byDomain.set(key, o);
}
const final = [...byDomain.values()];
if (!final.length) return [{ json: { no_results: true, search } }];
return final;

// Detects website signals from raw HTML
function detect(raw, hasWebsite) {
  raw = typeof raw === 'string' ? raw : '';
  const html = raw.toLowerCase();
  const has = (arr) => arr.some(k => html.includes(k));
  const bad = (e) => /\.(png|jpe?g|gif|webp|svg|css|js)$/i.test(e) || /(sentry|example\.|wixpress|domain\.com|yourname|email\.com|mhtml|\.blink$|^frame-)/i.test(e);
  const emails = [...new Set((raw.match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi) || []).map(e => e.toLowerCase()))].filter(e => !bad(e));
  const years = (raw.match(/(?:©|&copy;|&#169;|copyright)[^<\n]{0,25}?(20\d{2})/gi) || []).map(m => Number(m.match(/20\d{2}/g).pop()));
  const ok = !!hasWebsite && raw.length > 500;
  const BOOKING_KEYS = ['calendly.com','acuityscheduling','as.me/','setmore','squareup.com/appointments','square.site/book','book.squareup','zocdoc','vagaro.com','mindbodyonline','mindbody.io','booksy.com','fresha.com','simplybook','getweave','book.getweave','solutionreach','lh360','lighthouse360','yapiapp','yapi.me','modento','carestack','dentrixascend','curvehero','curvedental','denticon','patientpop','tebra.com','kareo','doctible','zenoti','joinblvd','blvd.co','glossgenius','housecallpro','getjobber','servicetitan','nexhealth','localmed','opencare.com','flexbook','calendar.app.google','bookings.cloud.microsoft','janeapp.com','cliniko.com','simplepractice.com','schedulicity','appointy','youcanbook.me','book now','book online','book an appointment','schedule online','schedule today','book a time'];
  const CHAT_KEYS = ['tawk.to','intercom','drift.com','crisp.chat','tidio','livechatinc','js.hs-scripts','zopim','podium','birdeye','manychat','connect.podium.com','bewebchat','widget.intercom.io','intercomcdn','js.driftt.com','cdn.livechat','js.usemessages.com','static.zdassets.com','olark','freshchat','smartsupp','chatra','userlike','jivosite','jivochat','salesiq.zoho','apexchat','ngagelive','widgets.leadconnectorhq','chatwoot','botpress','voiceflow','chatbase.co','landbot','kommunicate','comm100','lpsnmedia','liveperson','ada.support','signpost.com','broadly.com','thryv'];
  return {
    site_reachable: ok,
    email: emails[0] || '',
    has_booking: ok && has(BOOKING_KEYS),
    has_chat_widget: ok && has(CHAT_KEYS),
    has_contact_form: ok && html.includes('<form'),
    mobile_friendly: ok && /name=["']?viewport/.test(html),
    copyright_year: years.length ? Math.max(...years) : null
  };
}

const lead = $('Normalize & Dedupe').item.json;
const sig = detect($json.data, lead.has_website);
return { json: { ...lead, ...sig } };

