// Re-run detection on Firecrawl's rendered HTML (better data for JS-heavy / blocked sites)
const lead = $('Detect Website Signals').item.json;
const d = $json.data || {};
const raw = d.rawHtml || d.html || d.markdown || '';
if (!raw) return { json: lead };
const sig = detect(raw, true);
return { json: { ...lead, ...sig, email: lead.email || sig.email } };

// Rule-based opportunity score (transparent + explainable to clients)
const l = $json;
let s = 0;
const gaps = [];
if (!l.has_website) {
  if (l.social_url) { s += 40; gaps.push('Only a social media page, no website'); }
  else { s += 45; gaps.push('No website'); }
}
else if (!l.site_reachable) { gaps.push('Website could not be analyzed'); }
else {
  if (!l.has_booking) { s += 20; gaps.push('No online booking'); }
  if (!l.has_chat_widget) { s += 15; gaps.push('No live chat / after-hours support'); }
  if (!l.mobile_friendly) { s += 10; gaps.push('Not mobile-friendly'); }
  if (!l.has_contact_form) { s += 5; gaps.push('No contact form'); }
  if (l.copyright_year && l.copyright_year < new Date().getFullYear() - 1) { s += 10; gaps.push(`Outdated site (© ${l.copyright_year})`); }
}
if (l.unclaimed_profile) { s += 10; gaps.push('Google Business Profile not claimed'); }
if (l.rating >= 4.2 && l.reviews_count >= 50) s += 15;   // established business = has budget
if (!l.phone && !l.email) s -= 20;                       // hard to contact
s = Math.max(0, Math.min(100, s));
return { json: { ...l, opportunity_score: s, top_gaps: gaps.join(', '),
  priority: s >= 60 ? 'Hot' : s >= 35 ? 'Warm' : 'Cold' } };

