const lead = $('AI Batch Loop').item.json;
const o = ($json && $json.output) || {};
return { json: { ...lead,
  email_subject: o.email_subject || '',
  email_body: o.email_body || '',
  call_opener: o.call_opener || '',
  status: o.email_body ? 'Drafted' : 'AI Failed'
}};

const l = $json;
const yn = v => (v ? 'Yes' : 'No');
const waText = l.email_body ? '?text=' + encodeURIComponent(l.email_body) : '';
const wa = l.wa_number ? `https://wa.me/${l.wa_number}${waText}` : '';
return { json: {
  place_id: l.place_id, business_name: l.business_name, category: l.category,
  address: l.address, city: l.city, phone: l.phone, website: l.website,
  rating: l.rating, reviews_count: l.reviews_count, maps_url: l.maps_url,
  email: l.email || '', social_url: l.social_url || '', whatsapp_link: wa,
  unclaimed_profile: yn(l.unclaimed_profile),
  has_website: yn(l.has_website), has_booking: yn(l.has_booking),
  has_chat_widget: yn(l.has_chat_widget), has_contact_form: yn(l.has_contact_form),
  mobile_friendly: yn(l.mobile_friendly), copyright_year: l.copyright_year || '',
  opportunity_score: l.opportunity_score, priority: l.priority, top_gaps: l.top_gaps,
  email_subject: l.email_subject || '', email_body: l.email_body || '',
  call_opener: l.call_opener || '', status: l.status || 'New',
  search: l.search, scraped_at: l.scraped_at
}};

const rows = $('Prepare Sheet Row').all().map(i => i.json);
const f = $('Start Lead Search').first().json;
const count = p => rows.filter(r => r.priority === p).length;
return [{ json: {
  run_date: new Date().toISOString(),
  search: f['Business Type'],
  city: f['City or Area'],
  total: rows.length,
  hot: count('Hot'),
  warm: count('Warm'),
  cold: count('Cold'),
  emails_found: rows.filter(r => r.email).length
}}];

